alter table public.master_data add column if not exists priority_parent text; alter table public.master_data add column if not exists priority_order numeric; comment on column public.master_data.priority_parent is 'For routes: id of the priority (main) route this route shares its trip serial sequence with'; comment on column public.master_data.priority_order is 'Optional ordering number (1,2,3...) that sorts priority route groups in the trip list'